import{f as a,ag as s,o as i,s as n}from"./chunks/framework.D85dHE_g.js";const t="/assets/yarn.CV2d2sYf.png",r="/assets/yarn1.D1Lk4ztn.png",g=JSON.parse('{"title":"yarn 相关","description":"","frontmatter":{},"headers":[],"relativePath":"大前端/前端工具/yarn相关.md","filePath":"大前端/前端工具/yarn相关.md","lastUpdated":1735304697000}'),o={name:"大前端/前端工具/yarn相关.md"};function l(d,e,c,p,h,u){return s(),i("div",null,e[0]||(e[0]=[n('<h1 id="yarn-相关" tabindex="-1">yarn 相关 <a class="header-anchor" href="#yarn-相关" aria-label="Permalink to &quot;yarn 相关&quot;">​</a></h1><p>Yarn 是一个包管理器，同时也是项目管理器。多的话也不多说，反正你需要使用就行。</p><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><ul><li><code>node</code>方式</li></ul><p>如果已经安装 <code>node</code> 可以使用 <code>npm</code> 快速安装</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>npm install -g yarn</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="禁止运行-yarn" tabindex="-1">禁止运行 <code>yarn</code> <a class="header-anchor" href="#禁止运行-yarn" aria-label="Permalink to &quot;禁止运行 `yarn`&quot;">​</a></h2><p><img src="'+t+'" alt="禁止执行"></p><p><code>PowerShell</code> 执行策略，默认设置为 <code>Restricted</code> 不加载配置文件或运行脚本。需变更设置为 <code>RemoteSigned</code>，（简言之：因为电脑系统阻止了这个脚本的运行，对这个脚本不信任，所以我们要更改系统的权限）</p><ul><li>改为 <code>cmd</code> 执行</li></ul><p>最简单的解决方法是cmd代替powershell执行yarn命令</p><ul><li>更改 <code>ExecutionPolicy</code></li></ul><p>管理员身份打开 <code>PowerShell</code>, 执行一下命令</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>set-ExecutionPolicy RemoteSigned</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>过程中提示询问是否要更改执行策略?，选择 A 或 Y 。完成后执行 <code>get-ExecutionPolicy</code> 命令，若返回<code>RemoteSigned </code>则表示成功。</p><div class="warning custom-block"><p class="custom-block-title">注意</p><ol><li><p>如果还是不行则先卸载，执行命令 <code>npm uninstall -g yarn</code> ，再重新安装 <code>npm i yarn -g</code> ， 再次查看版本检验是否正常。</p></li><li><p>还有些情况比如说使用的是nvm控制nodejs的版本，下载的yarn包要放在对应nodejs版本的node_modules下面 <img src="'+r+'" alt="nvm对应版本下yarn"></p></li></ol></div><h2 id="error-certificate-has-expired问题" tabindex="-1">Error: certificate has expired问题 <a class="header-anchor" href="#error-certificate-has-expired问题" aria-label="Permalink to &quot;Error: certificate has expired问题&quot;">​</a></h2><p>按照依赖时报错，【HTTPS 证书验证失败】导致的这个问题！</p><p><strong>解决方案：</strong> 将yarn配置中的 strict-ssl 设置为 flase , 在 info yarn config 信息中， &#39;strict-ssl&#39; 为 true，表示需要验证 HTTPS 证书。我们可以将 &#39;strict-ssl&#39; 设置为 false，跳过 HTTPS 证书验证。</p><div class="language-js vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">yarn config set </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;strict-ssl&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div>',20)]))}const y=a(o,[["render",l]]);export{g as __pageData,y as default};
